int dist(int x, int y) {
    int maxDist = 0;
    int sumDist = 0;
    for (int i = 0; i < N; ++i) {
        int currentDist = abs(x - pos[i].FI) + abs(y - pos[i].SE);
        maxDist = max(maxDist, currentDist);
        sumDist += currentDist;
    }
    return maxDist + 2 * (sumDist - maxDist);
}

